def solo_guide_rows():
    g = SOLO_GUIDE
    rows = [g['title'], g['desc'], g['intro'], g['how'],
            [g['title'][0] + ' — OneSpace'] + [t + ' — OneSpace' for t in g['title'][1:]]]
    for heading, tips in g['sections']:
        rows.append(heading)
        rows.extend(tips)
    return rows
